/// Command-list forward and inverse (see [`crate::change_command::ChangeKitCommand`]).
pub mod kit_change {
    use serde::{Deserialize, Serialize};

    use crate::change_command::ChangeKitCommand;

    /// Semantic kind for a [`KitChange`] (VCS and UI; replaces the old `KitOperation` wrapper).
    #[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq, Hash, Default)]
    #[serde(rename_all = "camelCase")]
    pub enum KitChangeKind {
        #[default]
        Inferred,
        SetKitMetadata,
        AddType,
        RemoveType,
        ModifyType,
        AddDesign,
        RemoveDesign,
        ModifyDesign,
        AddPiece,
        RemovePiece,
        Connect,
        Disconnect,
        UnifyCheckpoints,
        MarkRelease,
        Other(String),
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default)]
    pub struct KitChange {
        /// Forward commands, applied in order.
        pub forward: Vec<ChangeKitCommand>,
        /// Inverse (undo) commands, applied in order to reverse [`KitChange::forward`].
        pub inverse: Vec<ChangeKitCommand>,
        /// Semantic label; defaults to [`KitChangeKind::Inferred`].
        #[serde(default, skip_serializing_if = "is_default_change_kind")]
        pub kind: KitChangeKind,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub author: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub time: Option<String>,
    }

    fn is_default_change_kind(k: &KitChangeKind) -> bool {
        *k == KitChangeKind::Inferred
    }

    impl KitChange {
        /// Apply the forward step to a store.
        pub fn apply_forward(c: &KitChange, kit: &crate::kit::KitStoreRef) -> crate::error::SetResult {
            ChangeKitCommand::apply_many(kit, &c.forward).map_err(|e| crate::error::SetError::Internal(format!("kit change forward: {e}")))?;
            Ok(())
        }

        /// Apply the backward (undo) step to a store.
        pub fn apply_backward(c: &KitChange, kit: &crate::kit::KitStoreRef) -> crate::error::SetResult {
            ChangeKitCommand::apply_many(kit, &c.inverse).map_err(|e| crate::error::SetError::Internal(format!("kit change backward: {e}")))?;
            Ok(())
        }
    }
}

pub mod error {
    use serde::{Deserialize, Serialize};
    use thiserror::Error;

    use crate::id::Id;

    /// 🧾 User-visible / wire rejection for a single field write (WASM + hooks).
    #[derive(Error, Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    #[serde(tag = "kind", content = "message")]
    pub enum SetError {
        #[error("illegal name: {0}")]
        IllegalName(String),
        #[error("name too long: {0}")]
        NameTooLong(String),
        #[error("invalid url: {0}")]
        InvalidUrl(String),
        #[error("invalid value: {0}")]
        InvalidValue(String),
        #[error("duplicate id: {0}")]
        DuplicateId(String),
        #[error("not found: {0}")]
        NotFound(String),
        #[error("cyclic reference: {0}")]
        CyclicReference(String),
        #[error("port family mismatch: {0}")]
        PortFamilyMismatch(String),
        #[error("readonly: {0}")]
        Readonly(String),
        #[error("disposed: {0}")]
        Disposed(String),
        #[error("timeout: {0}")]
        Timeout(String),
        #[error("lock poisoned: {0}")]
        LockPoisoned(String),
        #[error("internal: {0}")]
        Internal(String),
    }

    pub type SetResult = std::result::Result<(), SetError>;

    #[derive(Error, Debug)]
    pub enum SemioError {
        #[error("entity not found: {kind} '{id}'")]
        NotFound { kind: &'static str, id: Id },

        #[error("invalid operation: {0}")]
        InvalidOperation(String),

        #[error("lock poisoned accessing {0}")]
        LockPoisoned(&'static str),

        #[error("json error: {0}")]
        Json(#[from] serde_json::Error),

        #[error("io error: {0}")]
        Io(#[from] std::io::Error),

        #[cfg(not(target_arch = "wasm32"))]
        #[error("sqlite error: {0}")]
        Sqlite(#[from] rusqlite::Error),

        #[cfg(not(target_arch = "wasm32"))]
        #[error("zip error: {0}")]
        Zip(#[from] zip::result::ZipError),

        #[error("other: {0}")]
        Other(String),
    }

    pub type Result<T> = std::result::Result<T, SemioError>;

    impl From<SetError> for SemioError {
        fn from(e: SetError) -> Self {
            SemioError::InvalidOperation(e.to_string())
        }
    }
}

pub mod validate {
    //! 🧾 Field-level validation helpers returning [`crate::error::SetError`].

    use crate::error::{SetError, SetResult};

    const MAX_NAME_LEN: usize = 512;
    const MAX_KEY_LEN: usize = 256;
    const MAX_URL_LEN: usize = 4096;

    pub fn required_name(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::IllegalName(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_NAME_LEN {
            return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_NAME_LEN} chars")));
        }
        Ok(())
    }

    pub fn optional_display_name(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(x) => {
                let t = x.trim();
                if t.is_empty() {
                    return Err(SetError::IllegalName(format!("{label} cannot be empty")));
                }
                if t.len() > MAX_NAME_LEN {
                    return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_NAME_LEN} chars")));
                }
                Ok(())
            }
        }
    }

    pub fn required_non_empty(s: &str, label: &str) -> SetResult {
        if s.trim().is_empty() {
            return Err(SetError::InvalidValue(format!("{label} cannot be empty")));
        }
        Ok(())
    }

    pub fn required_url(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::InvalidUrl(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_URL_LEN {
            return Err(SetError::InvalidUrl(format!("{label} exceeds {MAX_URL_LEN} chars")));
        }
        if t.starts_with('/') || t.starts_with("./") {
            return Ok(());
        }
        if t.contains("://") {
            return Ok(());
        }
        Err(SetError::InvalidUrl(format!("{label} must be a URL or path")))
    }

    pub fn optional_url(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(u) => {
                if u.trim().is_empty() {
                    return Ok(());
                }
                required_url(u, label)
            }
        }
    }

    pub fn optional_opaque_uri(s: &Option<String>, label: &str) -> SetResult {
        match s {
            None => Ok(()),
            Some(u) => {
                let t = u.trim();
                if t.is_empty() {
                    return Ok(());
                }
                if t.len() > MAX_URL_LEN {
                    return Err(SetError::InvalidUrl(format!("{label} exceeds {MAX_URL_LEN} chars")));
                }
                Ok(())
            }
        }
    }

    pub fn email_basic(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::InvalidValue(format!("{label} cannot be empty")));
        }
        if !t.contains('@') || t.len() < 3 {
            return Err(SetError::InvalidValue(format!("{label} must look like an email")));
        }
        Ok(())
    }

    pub fn attribute_key(s: &str, label: &str) -> SetResult {
        let t = s.trim();
        if t.is_empty() {
            return Err(SetError::IllegalName(format!("{label} cannot be empty")));
        }
        if t.len() > MAX_KEY_LEN {
            return Err(SetError::NameTooLong(format!("{label} exceeds {MAX_KEY_LEN} chars")));
        }
        Ok(())
    }
}

pub mod events {
    //! Kit-scoped async broadcast bus (no tokio). WASM-safe.

    use std::sync::{Arc, Weak};

    use async_broadcast::{broadcast, InactiveReceiver, Receiver, Sender};

    use crate::id::Id;

    /// 🧭Entity discriminator for [`KitEvent`] payloads.
    #[derive(Clone, Copy, Debug, Eq, PartialEq, Hash, serde::Serialize)]
    pub enum EntityKind {
        Kit,
        Type,
        Design,
        Piece,
        Pose,
        Connection,
        Side,
        Port,
        Connector,
        Representation,
        File,
        Folder,
        Layer,
        Group,
        Author,
        Concept,
        Tag,
        Prop,
        Attribute,
        Quality,
        Stat,
        Benchmark,
        Family,
        Location,
    }

    /// 🪪Stable identity for event payloads.
    #[derive(Clone, Debug, Eq, PartialEq, Hash, serde::Serialize)]
    pub struct EntityRef {
        pub kind: EntityKind,
        pub id: Id,
    }

    impl EntityRef {
        pub const fn new(kind: EntityKind, id: Id) -> Self {
            Self { kind, id }
        }
    }

    macro_rules! event_field_enum {
        ($name:ident { $($variant:ident),+ $(,)? }) => {
            #[derive(Clone, Copy, Debug, Eq, PartialEq, Hash, serde::Serialize)]
            pub enum $name {
                $($variant),+
            }
        };
    }

    event_field_enum!(AttributeField { Key, Value, Definition });
    event_field_enum!(AuthorField { Name, Email, Role, Rank });
    event_field_enum!(BenchmarkField { Name, Min, Max, MinExcluded, MaxExcluded });
    event_field_enum!(ConceptField { Name, Description, Order });
    event_field_enum!(ConnectionField { Gap, Shift, Rise, Rotation, Turn, Tilt, X, Y, Description });
    event_field_enum!(ConnectorField { Code, Description, Port });
    event_field_enum!(DesignField { Name, Description, Icon, Image, Variant, View, Location, Camera, Unit, Created, Updated });
    event_field_enum!(FileField { Url, Mime, Size, Hash, Description, Created, Updated });
    event_field_enum!(FolderField { Path, Description });
    event_field_enum!(GroupField { Name, Description, Color, Icon, Pieces });
    event_field_enum!(KitField { Name, Description, Icon, Image, Preview, Version, Remote, Homepage, License, Uri, Created, Updated });
    event_field_enum!(LayerField { Name, Description, Color, Order, Visible, Locked });
    event_field_enum!(PieceField { Plane, Pose, Center, Color, Kind, Id, Name, Description, Scale, MirrorPlane, Hidden, Locked, FlatPlane, FlatCenter });
    event_field_enum!(PortField { Id, Family, CompatibleFamilies, Mandatory, T, Description, Point, Direction });
    event_field_enum!(PropField { Key, Value, Unit, Description });
    event_field_enum!(QualityField { Key, Value, Unit, Definition, Description });
    event_field_enum!(RepresentationField { Url, Description, File });
    event_field_enum!(SideField { Piece, Port, DesignPiece });
    event_field_enum!(StatField { Key, Value, Unit, Definition, Description });
    event_field_enum!(TagField { Name, Order });
    event_field_enum!(TypeField { Name, Description, Icon, Image, Variant, Stock, Virtual, Unit, Location, Created, Updated });

    macro_rules! scoped_event_enum {
        ($name:ident, $field:ident) => {
            #[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
            pub enum $name {
                Changed,
                FieldChanged($field),
            }
        };
    }

    scoped_event_enum!(AttributeEvent, AttributeField);
    scoped_event_enum!(AuthorEvent, AuthorField);
    scoped_event_enum!(BenchmarkEvent, BenchmarkField);
    scoped_event_enum!(ConceptEvent, ConceptField);
    scoped_event_enum!(ConnectionEvent, ConnectionField);
    scoped_event_enum!(ConnectorEvent, ConnectorField);
    scoped_event_enum!(FileEvent, FileField);
    scoped_event_enum!(FolderEvent, FolderField);
    scoped_event_enum!(GroupEvent, GroupField);
    scoped_event_enum!(LayerEvent, LayerField);
    scoped_event_enum!(PortEvent, PortField);
    scoped_event_enum!(PropEvent, PropField);
    scoped_event_enum!(QualityEvent, QualityField);
    scoped_event_enum!(RepresentationEvent, RepresentationField);
    scoped_event_enum!(SideEvent, SideField);
    scoped_event_enum!(StatEvent, StatField);
    scoped_event_enum!(TagEvent, TagField);

    #[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
    pub enum PieceEvent {
        Changed,
        FieldChanged(PieceField),
        DerivedChanged(PieceField),
    }

    #[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
    pub enum DesignEvent {
        Changed,
        FieldChanged(DesignField),
        Piece { piece_id: Id, event: PieceEvent },
        Connection { connection_id: Id, event: ConnectionEvent },
        Layer { layer_id: Id, event: LayerEvent },
        Group { group_id: Id, event: GroupEvent },
        Prop { prop_id: Id, event: PropEvent },
        Quality { quality_id: Id, event: QualityEvent },
        Stat { stat_id: Id, event: StatEvent },
        Tag { tag_id: Id, event: TagEvent },
        Attribute { attribute_id: Id, event: AttributeEvent },
        Author { author_id: Id, event: AuthorEvent },
        Concept { concept_id: Id, event: ConceptEvent },
    }

    #[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
    pub enum TypeEvent {
        Changed,
        FieldChanged(TypeField),
        Port { port_id: Id, event: PortEvent },
        Connector { connector_id: Id, event: ConnectorEvent },
        Representation { representation_id: Id, event: RepresentationEvent },
        Prop { prop_id: Id, event: PropEvent },
        Quality { quality_id: Id, event: QualityEvent },
        Stat { stat_id: Id, event: StatEvent },
        Tag { tag_id: Id, event: TagEvent },
        Attribute { attribute_id: Id, event: AttributeEvent },
    }

    /// 📣All observable changes on a kit graph.
    #[derive(Clone, Debug, PartialEq, serde::Serialize)]
    pub enum KitEvent {
        Changed,
        FieldChanged(KitField),
        Design { design_id: Id, event: DesignEvent },
        Type { type_id: Id, event: TypeEvent },
        Attribute { attribute_id: Id, event: AttributeEvent },
        Author { author_id: Id, event: AuthorEvent },
        Benchmark { benchmark_id: Id, event: BenchmarkEvent },
        Concept { concept_id: Id, event: ConceptEvent },
        Connection { connection_id: Id, event: ConnectionEvent },
        Connector { connector_id: Id, event: ConnectorEvent },
        File { file_id: Id, event: FileEvent },
        Folder { folder_id: Id, event: FolderEvent },
        Group { group_id: Id, event: GroupEvent },
        Layer { layer_id: Id, event: LayerEvent },
        Piece { piece_id: Id, event: PieceEvent },
        Port { port_id: Id, event: PortEvent },
        Tag { tag_id: Id, event: TagEvent },
        Prop { prop_id: Id, event: PropEvent },
        Quality { quality_id: Id, event: QualityEvent },
        Representation { representation_id: Id, event: RepresentationEvent },
        Side { side_id: Id, event: SideEvent },
        Stat { stat_id: Id, event: StatEvent },
        ChildAdded { parent: EntityRef, child: EntityRef },
        ChildRemoved { parent: EntityRef, child: EntityRef },
        HashInvalidated { entity: EntityRef },
        FlattenInvalidated { design: Id, pieces: Vec<Id> },
        ValidationInvalidated,
        SetRejected { event: Box<KitEvent>, error: crate::error::SetError },
    }

    impl KitEvent {
        pub fn cascade(&self) -> Vec<KitEvent> {
            let mut events = Vec::new();
            self.push_cascade(&mut events);
            events
        }

        fn push_cascade(&self, events: &mut Vec<KitEvent>) {
            match self {
                Self::Design { design_id, event } => {
                    events.push(Self::Changed);
                    events.push(Self::Design { design_id: design_id.clone(), event: DesignEvent::Changed });
                    event.push_cascade(design_id, events);
                }
                Self::Type { type_id, event } => {
                    events.push(Self::Changed);
                    events.push(Self::Type { type_id: type_id.clone(), event: TypeEvent::Changed });
                    event.push_cascade(type_id, events);
                }
                Self::SetRejected { .. } => events.push(self.clone()),
                Self::Changed => events.push(self.clone()),
                Self::FieldChanged(_) => {
                    events.push(Self::Changed);
                    events.push(self.clone());
                }
                _ => events.push(self.clone()),
            }
        }
    }

    impl DesignEvent {
        fn push_cascade(&self, design_id: &Id, events: &mut Vec<KitEvent>) {
            match self {
                Self::Piece { piece_id, event } => {
                    events.push(KitEvent::Design { design_id: design_id.clone(), event: Self::Piece { piece_id: piece_id.clone(), event: PieceEvent::Changed } });
                    if !matches!(event, PieceEvent::Changed) {
                        events.push(KitEvent::Design { design_id: design_id.clone(), event: self.clone() });
                    }
                }
                Self::Connection { connection_id, event } => {
                    events.push(KitEvent::Design { design_id: design_id.clone(), event: Self::Connection { connection_id: connection_id.clone(), event: ConnectionEvent::Changed } });
                    if !matches!(event, ConnectionEvent::Changed) {
                        events.push(KitEvent::Design { design_id: design_id.clone(), event: self.clone() });
                    }
                }
                Self::Changed => {}
                _ => events.push(KitEvent::Design { design_id: design_id.clone(), event: self.clone() }),
            }
        }
    }

    impl TypeEvent {
        fn push_cascade(&self, type_id: &Id, events: &mut Vec<KitEvent>) {
            match self {
                Self::Changed => {}
                _ => events.push(KitEvent::Type { type_id: type_id.clone(), event: self.clone() }),
            }
        }
    }

    /// 🛰️Broadcast channel wrapper; cloneable [`Sender`] shares one channel.
    #[derive(Debug)]
    pub struct EventBus {
        sender: Sender<KitEvent>,
        /// Keeps the channel open when no [`Receiver`] is subscribed yet (dropping the initial
        /// receiver from [`broadcast`] would close the channel and break all later subscribers).
        #[allow(dead_code)]
        _inactive: InactiveReceiver<KitEvent>,
    }

    impl EventBus {
        pub fn new(capacity: usize) -> Arc<Self> {
            let (mut sender, r) = broadcast(capacity);
            sender.set_overflow(true);
            let inactive = r.deactivate();
            Arc::new(Self { sender, _inactive: inactive })
        }

        pub fn subscribe(&self) -> Receiver<KitEvent> {
            self.sender.new_receiver()
        }

        pub fn emit(&self, event: KitEvent) {
            for event in event.cascade() {
                let _ = self.sender.try_broadcast(event);
            }
        }
    }

    #[inline]
    pub fn emit_weak(bus: &Weak<EventBus>, event: KitEvent) {
        if let Some(b) = bus.upgrade() {
            b.emit(event);
        }
    }
}

pub(crate) mod event_wire {
    //! Assign [`crate::events::EventBus`] weak handles to every node after kit construction.

    use std::sync::{Arc, Weak};

    use crate::benchmark::BenchmarkStoreRef;
    use crate::connection::ConnectionStoreRef;
    use crate::connector::ConnectorStoreRef;
    use crate::design::DesignStoreRef;
    use crate::events::EventBus;
    use crate::file::FileStoreRef;
    use crate::folder::FolderStoreRef;
    use crate::group::GroupStoreRef;
    use crate::kit::KitStoreRef;
    use crate::layer::LayerStoreRef;
    use crate::piece::PieceStoreRef;
    use crate::port::PortStoreRef;
    use crate::quality::QualityStoreRef;
    use crate::representation::RepresentationStoreRef;
    use crate::stat::StatStoreRef;
    use crate::typ::TypeStoreRef;

    pub(crate) fn wire_graph_bus(kit: &KitStoreRef) {
        let w = {
            let kr = kit.read().expect("kit read");
            Arc::downgrade(&kr.event_bus)
        };
        let kg = kit.read().expect("kit read");
        for t in &kg.types {
            wire_type(t, &w);
        }
        for d in &kg.designs {
            wire_design(d, &w);
        }
        for f in &kg.files {
            wire_file(f, &w);
        }
        for f in &kg.folders {
            wire_folder(f, &w);
        }
        for a in &kg.authors {
            if let Ok(mut g) = a.write() {
                g.event_bus = w.clone();
            }
        }
        for c in &kg.concepts {
            if let Ok(mut g) = c.write() {
                g.event_bus = w.clone();
            }
        }
        for t in &kg.tags {
            if let Ok(mut g) = t.write() {
                g.event_bus = w.clone();
            }
        }
        for q in &kg.qualities {
            wire_quality(q, &w);
        }
        for p in &kg.props {
            if let Ok(mut g) = p.write() {
                g.event_bus = w.clone();
            }
        }
        for a in &kg.attributes {
            if let Ok(mut g) = a.write() {
                g.event_bus = w.clone();
            }
        }
    }

    fn wire_type(t: &TypeStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = t.write() {
            g.event_bus = w.clone();
            for p in &g.ports {
                wire_port(p, w);
            }
            for c in &g.connectors {
                wire_connector(c, w);
            }
            for r in &g.representations {
                wire_representation(r, w);
            }
            for a in &g.authors {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
            for c in &g.concepts {
                if let Ok(mut cw) = c.write() {
                    cw.event_bus = w.clone();
                }
            }
            for tg in &g.tags {
                if let Ok(mut tw) = tg.write() {
                    tw.event_bus = w.clone();
                }
            }
            for q in &g.qualities {
                wire_quality(q, w);
            }
            for p in &g.props {
                if let Ok(mut pw) = p.write() {
                    pw.event_bus = w.clone();
                }
            }
            for a in &g.attributes {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
        }
    }

    fn wire_port(p: &PortStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = p.write() {
            g.event_bus = w.clone();
            for q in &g.qualities {
                wire_quality(q, w);
            }
            for a in g.attributes.iter_mut() {
                a.event_bus = w.clone();
            }
        }
    }

    fn wire_connector(c: &ConnectorStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = c.write() {
            g.event_bus = w.clone();
            for q in &g.qualities {
                wire_quality(q, w);
            }
            for a in g.attributes.iter_mut() {
                a.event_bus = w.clone();
            }
        }
    }

    fn wire_representation(r: &RepresentationStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = r.write() {
            g.event_bus = w.clone();
            for tg in g.tags.iter_mut() {
                tg.event_bus = w.clone();
            }
            for q in &g.qualities {
                wire_quality(q, w);
            }
            for a in g.attributes.iter_mut() {
                a.event_bus = w.clone();
            }
        }
    }

    fn wire_design(d: &DesignStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = d.write() {
            g.event_bus = w.clone();
            for p in &g.pieces {
                wire_piece(p, w);
            }
            for c in &g.connections {
                wire_connection(c, w);
            }
            for l in &g.layers {
                wire_layer(l, w);
            }
            for gr in &g.groups {
                wire_group(gr, w);
            }
            for a in &g.authors {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
            for c in &g.concepts {
                if let Ok(mut cw) = c.write() {
                    cw.event_bus = w.clone();
                }
            }
            for t in &g.tags {
                if let Ok(mut tw) = t.write() {
                    tw.event_bus = w.clone();
                }
            }
            for q in &g.qualities {
                wire_quality(q, w);
            }
            for p in &g.props {
                if let Ok(mut pw) = p.write() {
                    pw.event_bus = w.clone();
                }
            }
            for a in &g.attributes {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
            for s in &g.stats {
                wire_stat(s, w);
            }
        }
    }

    fn wire_piece(p: &PieceStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = p.write() {
            g.event_bus = w.clone();
            for pr in &g.props {
                if let Ok(mut pw) = pr.write() {
                    pw.event_bus = w.clone();
                }
            }
            for a in &g.attributes {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
        }
    }

    fn wire_connection(c: &ConnectionStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = c.write() {
            g.event_bus = w.clone();
            if let Ok(mut s) = g.connected.write() {
                s.event_bus = w.clone();
            }
            if let Ok(mut s) = g.connecting.write() {
                s.event_bus = w.clone();
            }
            for a in &g.attributes {
                if let Ok(mut aw) = a.write() {
                    aw.event_bus = w.clone();
                }
            }
        }
    }

    fn wire_layer(l: &LayerStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = l.write() {
            g.event_bus = w.clone();
        }
    }

    fn wire_group(gr: &GroupStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = gr.write() {
            g.event_bus = w.clone();
        }
    }

    fn wire_file(f: &FileStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = f.write() {
            g.event_bus = w.clone();
        }
    }

    fn wire_folder(f: &FolderStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = f.write() {
            g.event_bus = w.clone();
        }
    }

    fn wire_quality(q: &QualityStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = q.write() {
            g.event_bus = w.clone();
            for b in &g.benchmarks {
                wire_benchmark(b, w);
            }
        }
    }

    fn wire_stat(s: &StatStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = s.write() {
            g.event_bus = w.clone();
        }
    }

    fn wire_benchmark(b: &BenchmarkStoreRef, w: &Weak<EventBus>) {
        if let Ok(mut g) = b.write() {
            g.event_bus = w.clone();
        }
    }

    /// Re-point all `parent_kit` weak links at `kit` after in-place graph replacement (undo/redo).
    pub(crate) fn rewire_parent_kits(kit: &KitStoreRef) {
        let kw = Arc::downgrade(kit);
        let kg = kit.read().expect("kit read");
        for a in &kg.authors {
            if let Ok(mut aw) = a.write() {
                aw.parent_kit = Some(kw.clone());
            }
        }
        for c in &kg.concepts {
            if let Ok(mut cw) = c.write() {
                cw.parent_kit = Some(kw.clone());
            }
        }
        for t in &kg.tags {
            if let Ok(mut tw) = t.write() {
                tw.parent_kit = Some(kw.clone());
            }
        }
        for q in &kg.qualities {
            if let Ok(mut qw) = q.write() {
                qw.parent_kit = Some(kw.clone());
            }
        }
        for p in &kg.props {
            if let Ok(mut pw) = p.write() {
                pw.parent_kit = Some(kw.clone());
            }
        }
        for a in &kg.attributes {
            if let Ok(mut aw) = a.write() {
                aw.parent_kit = Some(kw.clone());
            }
        }
        for d in &kg.designs {
            if let Ok(mut dw) = d.write() {
                dw.parent_kit = kw.clone();
            }
        }
        for f in &kg.files {
            if let Ok(mut fw) = f.write() {
                fw.parent_kit = Some(kw.clone());
            }
        }
        for f in &kg.folders {
            if let Ok(mut fw) = f.write() {
                fw.parent_kit = Some(kw.clone());
            }
        }
    }
}

pub(crate) mod flatten_math {
    //! Geometric helpers for design flatten (mirrors `semio/py/main.py` plane/connector math).

    use nalgebra::{Matrix4, Vector3};

    use crate::geom::{Coordinate, Plane, Point, Vector};

    pub(crate) const FLATTEN_TOLERANCE: f64 = 1e-5;

    fn v3p(c: Point) -> Vector3<f64> {
        Vector3::new(c.x, c.y, c.z)
    }

    fn v3v(c: Vector) -> Vector3<f64> {
        Vector3::new(c.x, c.y, c.z)
    }

    fn point(v: Vector3<f64>) -> Point {
        Point::new(v.x, v.y, v.z)
    }

    fn gvec(v: Vector3<f64>) -> Vector {
        Vector::new(v.x, v.y, v.z)
    }

    fn normalize(v: Vector3<f64>) -> Vector3<f64> {
        let n = v.norm();
        if n < 1e-10 {
            Vector3::new(0.0, 0.0, 1.0)
        } else {
            v / n
        }
    }

    pub(crate) fn plane_to_matrix(p: &Plane) -> Matrix4<f64> {
        let o = v3p(p.origin);
        let x = normalize(v3v(p.x_axis));
        let y = normalize(v3v(p.y_axis));
        let z = normalize(x.cross(&y));
        let mut m = Matrix4::identity();
        m[(0, 0)] = x.x;
        m[(1, 0)] = x.y;
        m[(2, 0)] = x.z;
        m[(0, 1)] = y.x;
        m[(1, 1)] = y.y;
        m[(2, 1)] = y.z;
        m[(0, 2)] = z.x;
        m[(1, 2)] = z.y;
        m[(2, 2)] = z.z;
        m[(0, 3)] = o.x;
        m[(1, 3)] = o.y;
        m[(2, 3)] = o.z;
        m
    }

    pub(crate) fn matrix_to_plane(m: &Matrix4<f64>) -> Plane {
        let ox = m[(0, 3)];
        let oy = m[(1, 3)];
        let oz = m[(2, 3)];
        Plane {
            origin: Point::new(ox, oy, oz),
            x_axis: Vector::new(m[(0, 0)], m[(1, 0)], m[(2, 0)]),
            y_axis: Vector::new(m[(0, 1)], m[(1, 1)], m[(2, 1)]),
        }
    }

    // Quaternion (qx,qy,qz,qw) from two unit vectors
    fn quat_from_unit_vectors_full(v_from: Vector3<f64>, v_to: Vector3<f64>) -> (f64, f64, f64, f64) {
        let vf = normalize(v_from);
        let vt = normalize(v_to);
        let r = vf.dot(&vt) + 1.0;
        let (qx, qy, qz, qw) = if r < 0.000001 {
            if vf.x.abs() > vf.z.abs() {
                (-vf.y, vf.x, 0.0, 0.0)
            } else {
                (0.0, -vf.z, vf.y, 0.0)
            }
        } else {
            let c = vf.cross(&vt);
            (c.x, c.y, c.z, r)
        };
        let n = (qx * qx + qy * qy + qz * qz + qw * qw).sqrt();
        (qx / n, qy / n, qz / n, qw / n)
    }

    fn quat_from_axis_angle(axis: Vector3<f64>, angle: f64) -> (f64, f64, f64, f64) {
        let a = normalize(axis);
        let half = angle / 2.0;
        let s = half.sin();
        (a.x * s, a.y * s, a.z * s, half.cos())
    }

    fn quat_to_mat4(q: (f64, f64, f64, f64)) -> Matrix4<f64> {
        let (x, y, z, w) = q;
        let x2 = x + x;
        let y2 = y + y;
        let z2 = z + z;
        let xx = x * x2;
        let xy = x * y2;
        let xz = x * z2;
        let yy = y * y2;
        let yz = y * z2;
        let zz = z * z2;
        let wx = w * x2;
        let wy = w * y2;
        let wz = w * z2;
        let mut m = Matrix4::identity();
        m[(0, 0)] = 1.0 - (yy + zz);
        m[(0, 1)] = xy - wz;
        m[(0, 2)] = xz + wy;
        m[(1, 0)] = xy + wz;
        m[(1, 1)] = 1.0 - (xx + zz);
        m[(1, 2)] = yz - wx;
        m[(2, 0)] = xz - wy;
        m[(2, 1)] = yz + wx;
        m[(2, 2)] = 1.0 - (xx + yy);
        m
    }

    fn make_rotation_axis(axis: Vector3<f64>, angle: f64) -> Matrix4<f64> {
        quat_to_mat4(quat_from_axis_angle(axis, angle))
    }

    fn make_translation(x: f64, y: f64, z: f64) -> Matrix4<f64> {
        let mut m = Matrix4::identity();
        m[(0, 3)] = x;
        m[(1, 3)] = y;
        m[(2, 3)] = z;
        m
    }

    fn apply_mat3_upper(m: &Matrix4<f64>, v: Vector3<f64>) -> Vector3<f64> {
        Vector3::new(m[(0, 0)] * v.x + m[(0, 1)] * v.y + m[(0, 2)] * v.z, m[(1, 0)] * v.x + m[(1, 1)] * v.y + m[(1, 2)] * v.z, m[(2, 0)] * v.x + m[(2, 1)] * v.y + m[(2, 2)] * v.z)
    }

    fn round_tol(x: f64) -> f64 {
        (x / FLATTEN_TOLERANCE).round() * FLATTEN_TOLERANCE
    }

    /// `parent_connector` / `child_connector`: local anchor point + direction in type space.
    pub(crate) fn compute_child_plane(
        parent_plane: &Plane,
        parent_point: Point,
        parent_direction: Vector,
        child_point: Point,
        child_direction: Vector,
        gap: f64,
        shift: f64,
        rise: f64,
        rotation_deg: f64,
        turn_deg: f64,
        tilt_deg: f64,
    ) -> Plane {
        let parent_matrix = plane_to_matrix(parent_plane);
        let parent_pt = v3p(parent_point);
        let parent_dir = normalize(v3v(parent_direction));
        let child_pt = v3p(child_point);
        let child_dir = normalize(v3v(child_direction));

        let rotation_rad = rotation_deg.to_radians();
        let turn_rad = turn_deg.to_radians();
        let tilt_rad = tilt_deg.to_radians();

        let reverse_child_dir = -child_dir;
        let cross_vec = parent_dir.cross(&reverse_child_dir);
        let cross_len = cross_vec.norm();
        let align_quat = if cross_len < 0.01 {
            if parent_dir.z.abs() < FLATTEN_TOLERANCE {
                quat_from_axis_angle(Vector3::new(0.0, 0.0, 1.0), std::f64::consts::PI)
            } else {
                let axis = normalize(Vector3::new(0.0, 0.0, 1.0).cross(&parent_dir));
                quat_from_axis_angle(axis, std::f64::consts::PI)
            }
        } else {
            quat_from_unit_vectors_full(reverse_child_dir, parent_dir)
        };

        let direction_t = quat_to_mat4(align_quat);
        let y_axis = Vector3::new(0.0, 1.0, 0.0);
        let parent_connector_quat = quat_from_unit_vectors_full(y_axis, parent_dir);
        let parent_rotation_t = quat_to_mat4(parent_connector_quat);

        let gap_direction = apply_mat3_upper(&parent_rotation_t, Vector3::new(0.0, 1.0, 0.0));
        let shift_direction = apply_mat3_upper(&parent_rotation_t, Vector3::new(1.0, 0.0, 0.0));
        let raise_direction = apply_mat3_upper(&parent_rotation_t, Vector3::new(0.0, 0.0, 1.0));
        let mut turn_axis = apply_mat3_upper(&parent_rotation_t, Vector3::new(0.0, 0.0, 1.0));
        let mut tilt_axis = apply_mat3_upper(&parent_rotation_t, Vector3::new(1.0, 0.0, 0.0));

        let mut orientation_t = direction_t;
        let rotate_t = make_rotation_axis(parent_dir, -rotation_rad);
        orientation_t = rotate_t * orientation_t;
        turn_axis = apply_mat3_upper(&rotate_t, turn_axis);
        tilt_axis = apply_mat3_upper(&rotate_t, tilt_axis);
        let turn_t = make_rotation_axis(turn_axis, turn_rad);
        orientation_t = turn_t * orientation_t;
        let tilt_t = make_rotation_axis(tilt_axis, tilt_rad);
        orientation_t = tilt_t * orientation_t;

        let center_child_t = make_translation(-child_pt.x, -child_pt.y, -child_pt.z);
        let mut transform = orientation_t * center_child_t;

        let gap_transform = make_translation(gap_direction.x * gap, gap_direction.y * gap, gap_direction.z * gap);
        let shift_transform = make_translation(shift_direction.x * shift, shift_direction.y * shift, shift_direction.z * shift);
        let raise_transform = make_translation(raise_direction.x * rise, raise_direction.y * rise, raise_direction.z * rise);
        let translation_t = raise_transform * shift_transform * gap_transform;
        transform = translation_t * transform;
        let move_to_parent = make_translation(parent_pt.x, parent_pt.y, parent_pt.z);
        transform = move_to_parent * transform;

        let final_matrix = parent_matrix * transform;
        let mut pl = matrix_to_plane(&final_matrix);
        pl.origin = Point::new(round_tol(pl.origin.x), round_tol(pl.origin.y), round_tol(pl.origin.z));
        pl.x_axis = Vector::new(round_tol(pl.x_axis.x), round_tol(pl.x_axis.y), round_tol(pl.x_axis.z));
        pl.y_axis = Vector::new(round_tol(pl.y_axis.x), round_tol(pl.y_axis.y), round_tol(pl.y_axis.z));
        pl
    }

    pub(crate) const FLATTEN_RADIUS: f64 = 2.697;
    pub(crate) const FLATTEN_VERTICAL_V_EXTRA: f64 = 1.0;
    pub(crate) const FLATTEN_HORIZONTAL_SCALE: f64 = 3.0633;

    /// UV center for child from parent center and connection u/v (matches Python BFS).
    pub(crate) fn compute_child_center_uv(parent_center: Coordinate, connection_u: f64, connection_v: f64, parent_connector_dir_z: f64, parent_t: f64) -> Coordinate {
        let pu = parent_center.u;
        let pv = parent_center.v;
        if pu.abs() < FLATTEN_TOLERANCE && pv.abs() < FLATTEN_TOLERANCE {
            let angle = 2.0 * std::f64::consts::PI * parent_t;
            Coordinate::new(round_tol(FLATTEN_RADIUS * angle.sin()), round_tol(FLATTEN_RADIUS * angle.cos()))
        } else {
            let is_vertical = parent_connector_dir_z.abs() > 0.5;
            let (cu, cv) = if is_vertical { (pu + connection_u, pv + connection_v + FLATTEN_VERTICAL_V_EXTRA) } else { (pu + connection_u * FLATTEN_HORIZONTAL_SCALE, pv + connection_v * FLATTEN_HORIZONTAL_SCALE) };
            Coordinate::new(round_tol(cu), round_tol(cv))
        }
    }
}

pub mod file {
    use serde::{Deserialize, Serialize};
    use std::sync::{Arc, RwLock, Weak};

    use crate::events::{emit_weak, EntityKind, EntityRef, EventBus, KitEvent};
    use crate::hash::{Cache, HashWriter};
    use crate::id::Id;
    use crate::kit::KitStoreWeak;

    pub type FileStoreRef = Arc<RwLock<FileStore>>;
    pub type FileStoreWeak = Weak<RwLock<FileStore>>;

    /// External resource referenced by a kit (3D model, texture, etc.).
    #[derive(Debug)]
    pub struct FileStore {
        pub id: Id,
        pub url: String,
        pub mime: Option<String>,
        pub size: Option<i64>,
        pub hash: Option<String>,
        pub description: Option<String>,
        pub created: Option<String>,
        pub updated: Option<String>,
        pub parent_kit: Option<KitStoreWeak>,
        pub(crate) event_bus: Weak<EventBus>,
        hash_cache: Cache<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FileIdDto {
        pub id: Id,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FileMetadataDto {
        pub id: Id,
        pub url: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub mime: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub size: Option<i64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub hash: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub created: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub updated: Option<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FileShallowDto {
        pub id: Id,
        /// Metabolism: payload is often in `blob` (data URL) or a human `name`; we prefer a direct `url` when present.
        #[serde(default, alias = "blob", alias = "name")]
        pub url: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub mime: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub size: Option<i64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub hash: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none", alias = "createdAt")]
        pub created: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none", alias = "updatedAt")]
        pub updated: Option<String>,
    }

    /// Wire shape for [`FileFullDto`] (Metabolism: `name` + `blob` + `folder`, no top-level `url`).
    #[derive(Deserialize)]
    struct FileFullDtoWire {
        id: Id,
        url: Option<String>,
        name: Option<String>,
        #[serde(default)]
        blob: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        mime: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size: Option<i64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        hash: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none", alias = "createdAt")]
        created: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none", alias = "updatedAt")]
        updated: Option<String>,
    }

    impl From<FileFullDtoWire> for FileFullDto {
        fn from(w: FileFullDtoWire) -> Self {
            let url = w.url.or(w.blob).or(w.name).unwrap_or_default();
            FileFullDto { id: w.id, url, mime: w.mime, size: w.size, hash: w.hash, description: w.description, created: w.created, updated: w.updated }
        }
    }

    #[derive(Clone, Debug, Serialize, Default, PartialEq)]
    pub struct FileFullDto {
        pub id: Id,
        pub url: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub mime: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub size: Option<i64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub hash: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub created: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub updated: Option<String>,
    }

    impl<'de> Deserialize<'de> for FileFullDto {
        fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
            let w = FileFullDtoWire::deserialize(deserializer)?;
            Ok(FileFullDto::from(w))
        }
    }

    impl FileStore {
        pub fn new(url: impl Into<String>) -> Self {
            Self { id: Id::new_v7(), url: url.into(), mime: None, size: None, hash: None, description: None, created: None, updated: None, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        #[inline]
        fn emit_ev(&self, ev: KitEvent) {
            emit_weak(&self.event_bus, ev);
        }

        fn entity_ref(&self) -> EntityRef {
            EntityRef::new(EntityKind::File, self.id.clone())
        }

        pub fn from_id_dto(d: FileIdDto) -> Self {
            Self { id: d.id, url: String::new(), mime: None, size: None, hash: None, description: None, created: None, updated: None, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_metadata_dto(d: FileMetadataDto) -> Self {
            Self { id: d.id, url: d.url, mime: d.mime, size: d.size, hash: d.hash, description: d.description, created: d.created, updated: d.updated, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_shallow_dto(d: FileShallowDto) -> Self {
            Self::from_metadata_dto(FileMetadataDto { id: d.id, url: d.url, mime: d.mime, size: d.size, hash: d.hash, description: d.description, created: d.created, updated: d.updated })
        }

        pub fn from_full_dto(d: FileFullDto) -> Self {
            Self::from_metadata_dto(FileMetadataDto { id: d.id, url: d.url, mime: d.mime, size: d.size, hash: d.hash, description: d.description, created: d.created, updated: d.updated })
        }

        pub fn to_id_dto(&self) -> FileIdDto {
            FileIdDto { id: self.id.clone() }
        }

        pub fn to_metadata_dto(&self) -> FileMetadataDto {
            FileMetadataDto { id: self.id.clone(), url: self.url.clone(), mime: self.mime.clone(), size: self.size, hash: self.hash.clone(), description: self.description.clone(), created: self.created.clone(), updated: self.updated.clone() }
        }

        pub fn to_shallow_dto(&self) -> FileShallowDto {
            let m = self.to_metadata_dto();
            FileShallowDto { id: m.id, url: m.url, mime: m.mime, size: m.size, hash: m.hash, description: m.description, created: m.created, updated: m.updated }
        }

        pub fn to_full_dto(&self) -> FileFullDto {
            let m = self.to_metadata_dto();
            FileFullDto { id: m.id, url: m.url, mime: m.mime, size: m.size, hash: m.hash, description: m.description, created: m.created, updated: m.updated }
        }

        pub fn set_url(&mut self, url: String) -> crate::error::SetResult {
            if let Err(e) = crate::validate::required_url(&url, "url") {
                self.emit_ev(KitEvent::SetRejected { event: Box::new(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Url) }), error: e.clone() });
                return Err(e);
            }
            if self.url == url {
                return Ok(());
            }
            self.url = url;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Url) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_mime(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.mime == v {
                return Ok(());
            }
            self.mime = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Mime) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_size(&mut self, v: Option<i64>) -> crate::error::SetResult {
            if self.size == v {
                return Ok(());
            }
            self.size = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Size) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_hash(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.hash == v {
                return Ok(());
            }
            self.hash = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Hash) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_description(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.description == v {
                return Ok(());
            }
            self.description = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Description) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_created(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.created == v {
                return Ok(());
            }
            self.created = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Created) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_updated(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.updated == v {
                return Ok(());
            }
            self.updated = v;
            self.emit_ev(KitEvent::File { file_id: self.id.clone(), event: crate::events::FileEvent::FieldChanged(crate::events::FileField::Updated) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn apply_diff(&mut self, d: &crate::diff::FileDiff) -> crate::error::SetResult {
            if d.is_empty() {
                return Ok(());
            }
            if let Some(v) = &d.url {
                self.set_url(v.clone())?;
            }
            if let Some(v) = &d.mime {
                self.set_mime(v.clone())?;
            }
            if let Some(v) = &d.size {
                self.set_size(*v)?;
            }
            if let Some(v) = &d.hash {
                self.set_hash(v.clone())?;
            }
            if let Some(v) = &d.description {
                self.set_description(v.clone())?;
            }
            if let Some(v) = &d.created {
                self.set_created(v.clone())?;
            }
            if let Some(v) = &d.updated {
                self.set_updated(v.clone())?;
            }
            Ok(())
        }

        pub fn invalidate_hash(&self) {
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            if let Some(w) = &self.parent_kit {
                if let Some(k) = w.upgrade() {
                    if let Ok(kr) = k.read() {
                        kr.invalidate_hash();
                        kr.invalidate_validation();
                    }
                }
            }
        }

        pub fn hash(&self) -> String {
            self.hash_cache
                .get_or_init(|| {
                    let mut w = HashWriter::new();
                    self.hash_into(&mut w);
                    w.finalize()
                })
                .clone()
        }

        pub fn hash_into(&self, w: &mut HashWriter) {
            w.tag("file").str(self.id.as_str()).str(&self.url).opt_str(self.mime.as_deref()).opt_str(self.hash.as_deref());
            if let Some(s) = self.size {
                w.f64(s as f64);
            }
        }
    }
}

pub mod folder {
    use serde::{Deserialize, Serialize};
    use std::sync::{Arc, RwLock, Weak};

    use crate::events::{emit_weak, EntityKind, EntityRef, EventBus, KitEvent};
    use crate::hash::{Cache, HashWriter};
    use crate::id::Id;
    use crate::kit::KitStoreWeak;

    pub type FolderStoreRef = Arc<RwLock<FolderStore>>;
    pub type FolderStoreWeak = Weak<RwLock<FolderStore>>;

    /// Logical folder grouping files inside a kit.
    #[derive(Debug)]
    pub struct FolderStore {
        pub id: Id,
        pub path: String,
        pub description: Option<String>,
        pub parent_kit: Option<KitStoreWeak>,
        pub(crate) event_bus: Weak<EventBus>,
        hash_cache: Cache<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FolderIdDto {
        pub id: Id,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FolderMetadataDto {
        pub id: Id,
        pub path: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FolderShallowDto {
        pub id: Id,
        #[serde(default, alias = "name")]
        pub path: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct FolderFullDto {
        pub id: Id,
        #[serde(default, alias = "name")]
        pub path: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
    }

    impl FolderStore {
        pub fn new(path: impl Into<String>) -> Self {
            Self { id: Id::new_v7(), path: path.into(), description: None, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        #[inline]
        fn emit_ev(&self, ev: KitEvent) {
            emit_weak(&self.event_bus, ev);
        }

        fn entity_ref(&self) -> EntityRef {
            EntityRef::new(EntityKind::Folder, self.id.clone())
        }

        pub fn from_id_dto(d: FolderIdDto) -> Self {
            Self { id: d.id, path: String::new(), description: None, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_metadata_dto(d: FolderMetadataDto) -> Self {
            Self { id: d.id, path: d.path, description: d.description, parent_kit: None, event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_shallow_dto(d: FolderShallowDto) -> Self {
            Self::from_metadata_dto(FolderMetadataDto { id: d.id, path: d.path, description: d.description })
        }

        pub fn from_full_dto(d: FolderFullDto) -> Self {
            Self::from_metadata_dto(FolderMetadataDto { id: d.id, path: d.path, description: d.description })
        }

        pub fn to_id_dto(&self) -> FolderIdDto {
            FolderIdDto { id: self.id.clone() }
        }

        pub fn to_metadata_dto(&self) -> FolderMetadataDto {
            FolderMetadataDto { id: self.id.clone(), path: self.path.clone(), description: self.description.clone() }
        }

        pub fn to_shallow_dto(&self) -> FolderShallowDto {
            let m = self.to_metadata_dto();
            FolderShallowDto { id: m.id, path: m.path, description: m.description }
        }

        pub fn to_full_dto(&self) -> FolderFullDto {
            let m = self.to_metadata_dto();
            FolderFullDto { id: m.id, path: m.path, description: m.description }
        }

        pub fn set_path(&mut self, path: String) -> crate::error::SetResult {
            if self.path == path {
                return Ok(());
            }
            self.path = path;
            self.emit_ev(KitEvent::Folder { folder_id: self.id.clone(), event: crate::events::FolderEvent::FieldChanged(crate::events::FolderField::Path) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_description(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.description == v {
                return Ok(());
            }
            self.description = v;
            self.emit_ev(KitEvent::Folder { folder_id: self.id.clone(), event: crate::events::FolderEvent::FieldChanged(crate::events::FolderField::Description) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn apply_diff(&mut self, d: &crate::diff::FolderDiff) -> crate::error::SetResult {
            if d.is_empty() {
                return Ok(());
            }
            if let Some(v) = &d.path {
                self.set_path(v.clone())?;
            }
            if let Some(v) = &d.description {
                self.set_description(v.clone())?;
            }
            Ok(())
        }

        pub fn invalidate_hash(&self) {
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            if let Some(w) = &self.parent_kit {
                if let Some(k) = w.upgrade() {
                    if let Ok(kr) = k.read() {
                        kr.invalidate_hash();
                        kr.invalidate_validation();
                    }
                }
            }
        }

        pub fn hash(&self) -> String {
            self.hash_cache
                .get_or_init(|| {
                    let mut w = HashWriter::new();
                    self.hash_into(&mut w);
                    w.finalize()
                })
                .clone()
        }

        pub fn hash_into(&self, w: &mut HashWriter) {
            w.tag("folder").str(self.id.as_str()).str(&self.path).opt_str(self.description.as_deref());
        }
    }
}

pub mod geom {
    use serde::{Deserialize, Serialize};

    use crate::hash::HashWriter;
    use crate::merkle::Writer as MerkleWriter;

    /// 2D diagram coordinate (`hash_coordinate` in `semio/py/main.py` — "Coordinate" + u + v).
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct Coordinate {
        pub u: f64,
        pub v: f64,
    }

    #[derive(Deserialize)]
    #[serde(untagged)]
    enum PieceCenterWire {
        Uv { u: f64, v: f64 },
        /// Legacy: three floats saved as `x`/`y` — treated as (u, v) with z dropped.
        Xy { x: f64, y: f64 },
    }

    impl From<PieceCenterWire> for Coordinate {
        fn from(w: PieceCenterWire) -> Self {
            match w {
                PieceCenterWire::Uv { u, v } => Coordinate { u, v },
                PieceCenterWire::Xy { x, y } => Coordinate { u: x, v: y },
            }
        }
    }

    pub fn deserialize_option_piece_center<'de, D: serde::Deserializer<'de>>(d: D) -> Result<Option<Coordinate>, D::Error> {
        let o: Option<PieceCenterWire> = Option::deserialize(d)?;
        Ok(o.map(Into::into))
    }

    impl Coordinate {
        pub const ZERO: Coordinate = Coordinate { u: 0.0, v: 0.0 };

        pub fn new(u: f64, v: f64) -> Self {
            Self { u, v }
        }

        /// Fast path for in-memory / entity [`HashWriter`] (tag-based) — not the Python Merkle.
        pub fn hash_into(&self, w: &mut HashWriter) {
            w.f64(self.u).f64(self.v);
        }

        /// Python `hash_coordinate` (prefix "Coordinate" + u + v)
        pub fn merkle_hash(&self) -> String {
            let mut w = MerkleWriter::new();
            w.string("Coordinate");
            w.string("u");
            w.number(self.u);
            w.string("v");
            w.number(self.v);
            w.digest()
        }
    }

    /// 2D screen offset (Python `hash_vec` "Vec" + u + v). Same field layout as [`Coordinate`].
    pub type Uv = Coordinate;

    /// 3D point (`hash_point` in `semio/py/main.py`).
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct Point {
        pub x: f64,
        pub y: f64,
        pub z: f64,
    }

    impl Point {
        pub const ZERO: Point = Point { x: 0.0, y: 0.0, z: 0.0 };
        pub fn new(x: f64, y: f64, z: f64) -> Self {
            Self { x, y, z }
        }
        pub fn hash_into(&self, w: &mut HashWriter) {
            w.f64(self.x).f64(self.y).f64(self.z);
        }
        pub fn merkle_hash(&self) -> String {
            let mut w = MerkleWriter::new();
            w.string("Point");
            w.string("x");
            w.number(self.x);
            w.string("y");
            w.number(self.y);
            w.string("z");
            w.number(self.z);
            w.digest()
        }

        /// Translate by a direction vector.
        pub fn add_vec(&self, v: &Vector) -> Point {
            Point::new(self.x + v.x, self.y + v.y, self.z + v.z)
        }
    }

    /// 3D direction (`hash_vector` in `semio/py/main.py`). Not necessarily unit length.
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct Vector {
        pub x: f64,
        pub y: f64,
        pub z: f64,
    }

    impl Vector {
        pub const X: Vector = Vector { x: 1.0, y: 0.0, z: 0.0 };
        pub const Y: Vector = Vector { x: 0.0, y: 1.0, z: 0.0 };
        pub const Z: Vector = Vector { x: 0.0, y: 0.0, z: 1.0 };

        pub fn new(x: f64, y: f64, z: f64) -> Self {
            Self { x, y, z }
        }
        pub fn add(&self, o: &Vector) -> Vector {
            Vector::new(self.x + o.x, self.y + o.y, self.z + o.z)
        }
        pub fn sub(&self, o: &Vector) -> Vector {
            Vector::new(self.x - o.x, self.y - o.y, self.z - o.z)
        }
        pub fn scale(&self, s: f64) -> Vector {
            Vector::new(self.x * s, self.y * s, self.z * s)
        }
        pub fn length(&self) -> f64 {
            (self.x * self.x + self.y * self.y + self.z * self.z).sqrt()
        }
        pub fn cross(&self, o: &Vector) -> Vector {
            Vector::new(
                self.y * o.z - self.z * o.y,
                self.z * o.x - self.x * o.z,
                self.x * o.y - self.y * o.x,
            )
        }
        pub fn hash_into(&self, w: &mut HashWriter) {
            w.f64(self.x).f64(self.y).f64(self.z);
        }
        pub fn merkle_hash(&self) -> String {
            let mut w = MerkleWriter::new();
            w.string("Vector");
            w.string("x");
            w.number(self.x);
            w.string("y");
            w.number(self.y);
            w.string("z");
            w.number(self.z);
            w.digest()
        }
    }

    /// Oriented plane: origin, x-axis, y-axis (Python `hash_plane`).
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct Plane {
        #[serde(default)]
        pub origin: Point,
        #[serde(default = "Plane::def_x", rename = "xAxis")]
        pub x_axis: Vector,
        #[serde(default = "Plane::def_y", rename = "yAxis")]
        pub y_axis: Vector,
    }

    impl Plane {
        fn def_x() -> Vector {
            Vector::X
        }
        fn def_y() -> Vector {
            Vector::Y
        }
        pub fn world_xy() -> Self {
            Self { origin: Point::ZERO, x_axis: Vector::X, y_axis: Vector::Y }
        }
        pub fn hash_into(&self, w: &mut HashWriter) {
            self.origin.hash_into(w);
            self.x_axis.hash_into(w);
            self.y_axis.hash_into(w);
        }
        pub fn merkle_hash(&self) -> String {
            let mut w = MerkleWriter::new();
            w.string("Plane");
            w.string("origin");
            w.sub_hash(&self.origin.merkle_hash());
            w.string("xAxis");
            w.sub_hash(&self.x_axis.merkle_hash());
            w.string("yAxis");
            w.sub_hash(&self.y_axis.merkle_hash());
            w.digest()
        }
    }

    /// View camera (`hash_camera` in `semio/py/main.py` — position, forward, up).
    #[derive(Clone, Copy, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct Camera {
        #[serde(default)]
        pub position: Point,
        #[serde(default)]
        pub forward: Vector,
        #[serde(default = "Camera::def_up")]
        pub up: Vector,
    }

    impl Camera {
        fn def_up() -> Vector {
            Vector::Z
        }
        pub fn merkle_hash(&self) -> String {
            let mut w = MerkleWriter::new();
            w.string("Camera");
            w.string("forward");
            w.sub_hash(&self.forward.merkle_hash());
            w.string("position");
            w.sub_hash(&self.position.merkle_hash());
            w.string("up");
            w.sub_hash(&self.up.merkle_hash());
            w.digest()
        }
    }
}

