pub mod group {
    use serde::{Deserialize, Serialize};
    use std::sync::{Arc, RwLock, Weak};

    use crate::events::{emit_weak, EntityKind, EntityRef, EventBus, KitEvent};
    use crate::hash::{Cache, HashWriter};
    use crate::id::Id;
    use crate::piece::{PieceIdDto, PieceStoreWeak};

    pub type GroupStoreRef = Arc<RwLock<GroupStore>>;
    pub type GroupStoreWeak = Weak<RwLock<GroupStore>>;

    /// User-defined group of pieces inside a [`crate::design::DesignStore`].
    #[derive(Debug)]
    pub struct GroupStore {
        pub id: Id,
        pub name: String,
        pub description: Option<String>,
        pub color: Option<String>,
        pub icon: Option<String>,
        pub pieces: Vec<PieceStoreWeak>,
        pub parent_design: Weak<RwLock<crate::design::DesignStore>>,
        pub(crate) event_bus: Weak<EventBus>,
        hash_cache: Cache<String>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct GroupIdDto {
        pub id: Id,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct GroupMetadataDto {
        pub id: Id,
        pub name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub color: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub icon: Option<String>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub pieces: Vec<PieceIdDto>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct GroupShallowDto {
        pub id: Id,
        pub name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub color: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub icon: Option<String>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub pieces: Vec<PieceIdDto>,
    }

    #[derive(Clone, Debug, Serialize, Deserialize, Default, PartialEq)]
    pub struct GroupFullDto {
        pub id: Id,
        pub name: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub description: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub color: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub icon: Option<String>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        pub pieces: Vec<PieceIdDto>,
    }

    impl GroupStore {
        pub fn new(name: impl Into<String>) -> Self {
            Self { id: Id::new_v7(), name: name.into(), description: None, color: None, icon: None, pieces: Vec::new(), parent_design: Weak::new(), event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_id_dto(d: GroupIdDto) -> Self {
            Self { id: d.id, name: String::new(), description: None, color: None, icon: None, pieces: Vec::new(), parent_design: Weak::new(), event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_metadata_dto(d: GroupMetadataDto) -> Self {
            Self { id: d.id, name: d.name, description: d.description, color: d.color, icon: d.icon, pieces: Vec::new(), parent_design: Weak::new(), event_bus: Weak::new(), hash_cache: Cache::default() }
        }

        pub fn from_shallow_dto(d: GroupShallowDto) -> Self {
            Self::from_metadata_dto(GroupMetadataDto { id: d.id, name: d.name, description: d.description, color: d.color, icon: d.icon, pieces: d.pieces })
        }

        pub fn from_full_dto(d: GroupFullDto) -> Self {
            Self::from_metadata_dto(GroupMetadataDto { id: d.id, name: d.name, description: d.description, color: d.color, icon: d.icon, pieces: d.pieces })
        }

        pub fn to_id_dto(&self) -> GroupIdDto {
            GroupIdDto { id: self.id.clone() }
        }

        pub fn to_metadata_dto(&self) -> GroupMetadataDto {
            GroupMetadataDto {
                id: self.id.clone(),
                name: self.name.clone(),
                description: self.description.clone(),
                color: self.color.clone(),
                icon: self.icon.clone(),
                pieces: self.pieces.iter().filter_map(|p| p.upgrade()).filter_map(|p| p.read().ok().map(|p| p.to_id_dto())).collect(),
            }
        }

        pub fn to_shallow_dto(&self) -> GroupShallowDto {
            let m = self.to_metadata_dto();
            GroupShallowDto { id: m.id, name: m.name, description: m.description, color: m.color, icon: m.icon, pieces: m.pieces }
        }

        pub fn to_full_dto(&self) -> GroupFullDto {
            let m = self.to_metadata_dto();
            GroupFullDto { id: m.id, name: m.name, description: m.description, color: m.color, icon: m.icon, pieces: m.pieces }
        }

        #[inline]
        fn emit_ev(&self, ev: KitEvent) {
            emit_weak(&self.event_bus, ev);
        }

        fn entity_ref(&self) -> EntityRef {
            EntityRef::new(EntityKind::Group, self.id.clone())
        }

        pub fn set_name(&mut self, name: String) -> crate::error::SetResult {
            if self.name == name {
                return Ok(());
            }
            self.name = name;
            self.emit_ev(KitEvent::Group { group_id: self.id.clone(), event: crate::events::GroupEvent::FieldChanged(crate::events::GroupField::Name) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_description(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.description == v {
                return Ok(());
            }
            self.description = v;
            self.emit_ev(KitEvent::Group { group_id: self.id.clone(), event: crate::events::GroupEvent::FieldChanged(crate::events::GroupField::Description) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_color(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.color == v {
                return Ok(());
            }
            self.color = v;
            self.emit_ev(KitEvent::Group { group_id: self.id.clone(), event: crate::events::GroupEvent::FieldChanged(crate::events::GroupField::Color) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_icon(&mut self, v: Option<String>) -> crate::error::SetResult {
            if self.icon == v {
                return Ok(());
            }
            self.icon = v;
            self.emit_ev(KitEvent::Group { group_id: self.id.clone(), event: crate::events::GroupEvent::FieldChanged(crate::events::GroupField::Icon) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn set_pieces(&mut self, pieces: Vec<PieceStoreWeak>) -> crate::error::SetResult {
            self.pieces = pieces;
            self.emit_ev(KitEvent::Group { group_id: self.id.clone(), event: crate::events::GroupEvent::FieldChanged(crate::events::GroupField::Pieces) });
            self.invalidate_hash();
            Ok(())
        }

        pub fn invalidate_hash(&self) {
            self.hash_cache.invalidate();
            self.emit_ev(KitEvent::HashInvalidated { entity: self.entity_ref() });
            if let Some(d) = self.parent_design.upgrade() {
                if let Ok(dr) = d.read() {
                    dr.invalidate_hash();
                }
            }
        }

        pub fn hash(&self) -> String {
            self.hash_cache
                .get_or_init(|| {
                    let mut w = HashWriter::new();
                    self.hash_into(&mut w);
                    w.finalize()
                })
                .clone()
        }

        pub fn hash_into(&self, w: &mut HashWriter) {
            w.tag("group").str(self.id.as_str()).str(&self.name).opt_str(self.description.as_deref()).opt_str(self.color.as_deref()).opt_str(self.icon.as_deref());
            for p in &self.pieces {
                if let Some(p) = p.upgrade() {
                    if let Ok(p) = p.read() {
                        w.str(p.id.as_str());
                    }
                }
            }
        }
    }
}

pub mod id {
    use serde::{Deserialize, Serialize};
    use std::borrow::Borrow;
    use std::fmt;
    use std::ops::Deref;

    /// Stable identity used at serialization boundaries and as a dictionary key when
    /// resolving DTOs into the in-memory graph. Never used for in-graph traversal.
    #[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize, PartialOrd, Ord)]
    #[serde(transparent)]
    pub struct Id(String);

    impl Id {
        /// Produces a fresh UUIDv7 (monotonic) wrapped as a `Id`.
        pub fn new_v7() -> Self {
            Self(uuid::Uuid::now_v7().to_string())
        }

        /// Borrow the underlying string slice.
        pub fn as_str(&self) -> &str {
            &self.0
        }

        /// Consume the [`Id`], returning the inner [`String`].
        pub fn into_string(self) -> String {
            self.0
        }
    }

    impl fmt::Display for Id {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str(&self.0)
        }
    }

    impl Deref for Id {
        type Target = str;
        fn deref(&self) -> &str {
            &self.0
        }
    }

    impl AsRef<str> for Id {
        fn as_ref(&self) -> &str {
            &self.0
        }
    }

    impl Borrow<str> for Id {
        fn borrow(&self) -> &str {
            &self.0
        }
    }

    impl From<String> for Id {
        fn from(s: String) -> Self {
            Self(s)
        }
    }

    impl From<&str> for Id {
        fn from(s: &str) -> Self {
            Self(s.to_owned())
        }
    }

    impl From<Id> for String {
        fn from(g: Id) -> Self {
            g.0
        }
    }

    impl PartialEq<str> for Id {
        fn eq(&self, other: &str) -> bool {
            self.0 == other
        }
    }

    impl PartialEq<&str> for Id {
        fn eq(&self, other: &&str) -> bool {
            self.0 == *other
        }
    }
}

pub mod hash {
    use sha2::{Digest, Sha256};
    use std::sync::Mutex;

    /// Interior-mutable lazy cache. Enables `invalidate_*(&self)` on entities so
    /// children can bubble invalidation via `parent.read()?.invalidate_hash()`
    /// without acquiring a write lock on the parent.
    #[derive(Debug)]
    pub struct Cache<T> {
        inner: Mutex<Option<T>>,
    }

    impl<T> Default for Cache<T> {
        fn default() -> Self {
            Self { inner: Mutex::new(None) }
        }
    }

    impl<T: Clone> Cache<T> {
        pub fn new() -> Self {
            Self::default()
        }

        pub fn get_or_init<F: FnOnce() -> T>(&self, f: F) -> T {
            let mut g = self.inner.lock().expect("cache poisoned");
            if g.is_none() {
                *g = Some(f());
            }
            g.clone().unwrap()
        }

        pub fn invalidate(&self) {
            *self.inner.lock().expect("cache poisoned") = None;
        }
    }

    /// Stable content-hash writer that feeds `sha2::Sha256` with deterministic
    /// string primitives. Used by domain entities to produce their own canonical
    /// hash fingerprint on demand.
    pub struct HashWriter {
        inner: Sha256,
    }

    impl HashWriter {
        pub fn new() -> Self {
            Self { inner: Sha256::new() }
        }

        pub fn tag(&mut self, tag: &str) -> &mut Self {
            self.inner.update(tag.as_bytes());
            self.inner.update(b"\0");
            self
        }

        pub fn str(&mut self, s: &str) -> &mut Self {
            self.inner.update((s.len() as u64).to_le_bytes());
            self.inner.update(s.as_bytes());
            self
        }

        pub fn opt_str(&mut self, s: Option<&str>) -> &mut Self {
            match s {
                Some(v) => {
                    self.inner.update(b"S");
                    self.str(v);
                }
                None => {
                    self.inner.update(b"N");
                }
            }
            self
        }

        pub fn f64(&mut self, v: f64) -> &mut Self {
            self.inner.update(v.to_le_bytes());
            self
        }

        pub fn opt_f64(&mut self, v: Option<f64>) -> &mut Self {
            match v {
                Some(x) => {
                    self.inner.update(b"F");
                    self.f64(x);
                }
                None => {
                    self.inner.update(b"N");
                }
            }
            self
        }

        pub fn bool(&mut self, v: bool) -> &mut Self {
            self.inner.update([if v { 1u8 } else { 0u8 }]);
            self
        }

        pub fn opt_bool(&mut self, v: Option<bool>) -> &mut Self {
            match v {
                Some(x) => {
                    self.inner.update(b"B");
                    self.bool(x);
                }
                None => {
                    self.inner.update(b"N");
                }
            }
            self
        }

        pub fn finalize(self) -> String {
            hex::encode(self.inner.finalize())
        }
    }

    impl Default for HashWriter {
        fn default() -> Self {
            Self::new()
        }
    }
}

/// 🧾Merkle writer matching `semio/py/main.py` `HashWriter` (SHA-256 over structured bytestream).
/// Used to produce the same `digest()` values as `hash_coordinate` / `hash_kit` / … in Python.
pub mod merkle {
    use sha2::{Digest, Sha256};

    /// Same rules as `main.py` `\_format_number_for_hash`.
    pub fn format_number(n: f64) -> String {
        if n.is_finite() && n.fract() == 0.0 {
            format!("{}", n as i64)
        } else {
            n.to_string()
        }
    }

    /// Structured writer — byte layout matches `HashWriter` in `semio/py/main.py`.
    pub struct Writer {
        parts: Vec<u8>,
    }

    impl Writer {
        pub fn new() -> Self {
            Self { parts: Vec::new() }
        }

        fn write_string_bytes(&mut self, s: &str) {
            let b = s.as_bytes();
            self.parts.extend((b.len() as u32).to_be_bytes());
            self.parts.extend(b);
        }

        /// Python `writeString(s)` — `>I` length big-endian + utf-8
        pub fn string(&mut self, s: &str) {
            self.write_string_bytes(s);
        }

        /// Python `writeNumber(n)` — as decimal string, formatted like JS Number.toString
        pub fn number(&mut self, n: f64) {
            self.write_string_bytes(&format_number(n));
        }

        pub fn bool(&mut self, b: bool) {
            self.parts.push(u8::from(b));
        }

        /// Python `writeHash` — 64-char hex digest written as a string
        pub fn sub_hash(&mut self, h: &str) {
            self.write_string_bytes(h);
        }

        /// Sorted hex hashes, count big-endian, then each string
        pub fn hash_list_sorted(&mut self, mut hashes: Vec<String>) {
            hashes.sort();
            self.parts.extend((hashes.len() as u32).to_be_bytes());
            for h in hashes {
                self.write_string_bytes(&h);
            }
        }

        /// Sorted id strings, count big-endian, then each string
        pub fn id_list_sorted(&mut self, mut ids: Vec<String>) {
            ids.sort();
            self.parts.extend((ids.len() as u32).to_be_bytes());
            for g in ids {
                self.write_string_bytes(&g);
            }
        }

        pub fn digest(self) -> String {
            hex::encode(Sha256::digest(&self.parts))
        }
    }

    impl Default for Writer {
        fn default() -> Self {
            Self::new()
        }
    }
}

