        fn quality_key_index(qualities: &[QualityFullDto]) -> HashMap<Id, String> {
            qualities.iter().map(|q| (q.id.clone(), q.key.clone())).collect()
        }

        fn apply_resolved_prop_key(quality_id_to_key: &HashMap<Id, String>, p: &mut PropFullDto) {
            if !p.key.is_empty() {
                return;
            }
            if let Some(qr) = &p.quality {
                if let Some(k) = quality_id_to_key.get(&qr.id) {
                    p.key = k.clone();
                }
            }
        }

        /// C# / Metabolism JSON: props use `quality: { id }` without a separate `key`; keys come from the kit's quality catalog.
        fn wire_compat_resolve_prop_keys_in_kit_dto(d: &mut KitFullDto) {
            let m = Self::quality_key_index(&d.qualities);
            for p in &mut d.props {
                Self::apply_resolved_prop_key(&m, p);
            }
            for t in &mut d.types {
                for p in &mut t.props {
                    Self::apply_resolved_prop_key(&m, p);
                }
            }
            for design in &mut d.designs {
                for p in &mut d.props {
                    Self::apply_resolved_prop_key(&m, p);
                }
                for piece in &mut design.pieces {
                    for p in &mut piece.props {
                        Self::apply_resolved_prop_key(&m, p);
                    }
                }
            }
        }

        /// Hydrate the full kit graph from a [`KitFullDto`].
        pub fn from_full_dto(mut d: KitFullDto) -> KitStoreRef {
            Self::wire_compat_resolve_prop_keys_in_kit_dto(&mut d);
            let vcs_root = d.clone();
            let KitFullDto { id, name, description, icon, image, preview, version, remote, homepage, license, uri, created, updated, types, designs, files, folders, authors, concepts, tags, qualities, props, attributes } = d;

            let kit = Arc::new(RwLock::new(KitStore {
                id: id.clone(),
                name: name.clone(),
                description: description.clone(),
                icon: icon.clone(),
                image: image.clone(),
                preview: preview.clone(),
                version: version.clone(),
                remote: remote.clone(),
                homepage: homepage.clone(),
                license: license.clone(),
                uri: uri.clone(),
                created: created.clone(),
                updated: updated.clone(),
                types: Vec::new(),
                designs: Vec::new(),
                files: Vec::new(),
                folders: Vec::new(),
                authors: authors.into_iter().map(|a| Arc::new(RwLock::new(AuthorStore::from_full_dto(a)))).collect(),
                concepts: concepts.into_iter().map(|c| Arc::new(RwLock::new(ConceptStore::from_full_dto(c)))).collect(),
                tags: tags.into_iter().map(|t| Arc::new(RwLock::new(TagStore::from_full_dto(t)))).collect(),
                qualities: qualities.into_iter().map(|q| Arc::new(RwLock::new(QualityStore::from_full_dto(q)))).collect(),
                props: props.into_iter().map(|p| Arc::new(RwLock::new(PropStore::from_full_dto(p)))).collect(),
                attributes: attributes.into_iter().map(|a| Arc::new(RwLock::new(AttributeStore::from_full_dto(a)))).collect(),
                event_bus: EventBus::new(4096),
                hash_cache: Cache::default(),
                validation_cache: Cache::default(),
                undo_past: Vec::new(),
                undo_future: Vec::new(),
                undo_inhibit: 0,
                initial: vcs_root,
                checkpoints: std::collections::HashMap::new(),
                alternatives: std::collections::HashMap::new(),
                the_kit_head: None,
                sessions: std::collections::HashMap::new(),
                children: std::collections::HashMap::new(),
            }));

            let kw = Arc::downgrade(&kit);
            if let Ok(k) = kit.write() {
                for a in &k.authors {
                    if let Ok(mut aw) = a.write() {
                        aw.parent_kit = Some(kw.clone());
                    }
                }
                for c in &k.concepts {
                    if let Ok(mut cw) = c.write() {
                        cw.parent_kit = Some(kw.clone());
                    }
                }
                for t in &k.tags {
                    if let Ok(mut tw) = t.write() {
                        tw.parent_kit = Some(kw.clone());
                    }
                }
                for q in &k.qualities {
                    if let Ok(mut qw) = q.write() {
                        qw.parent_kit = Some(kw.clone());
                    }
                }
                for p in &k.props {
                    if let Ok(mut pw) = p.write() {
                        pw.parent_kit = Some(kw.clone());
                    }
                }
                for a in &k.attributes {
                    if let Ok(mut aw) = a.write() {
                        aw.parent_kit = Some(kw.clone());
                    }
                }
            }

            let file_refs: Vec<FileStoreRef> = files.into_iter().map(|f| Arc::new(RwLock::new(FileStore::from_full_dto(f)))).collect();
            let folder_refs: Vec<FolderStoreRef> = folders.into_iter().map(|f| Arc::new(RwLock::new(FolderStore::from_full_dto(f)))).collect();

            let mut type_refs: Vec<TypeStoreRef> = Vec::with_capacity(types.len());
            let mut type_index: HashMap<Id, TypeStoreRef> = HashMap::new();
            for tdto in types {
                let t = TypeStore::hydrate_from_full_dto(tdto, &kit, &file_refs);
                if let Ok(tr) = t.read() {
                    type_index.insert(tr.id.clone(), t.clone());
                }
                type_refs.push(t);
            }

            let design_refs: Vec<DesignStoreRef> = designs
                .into_iter()
                .map(|ddto| {
                    let design = DesignStore::hydrate_from_full_dto(ddto, &type_index);
                    if let Ok(mut dw) = design.write() {
                        dw.parent_kit = Arc::downgrade(&kit);
                    }
                    design
                })
                .collect();

            if let Ok(mut k) = kit.write() {
                let kw = Arc::downgrade(&kit);
                for f in &file_refs {
                    if let Ok(mut fw) = f.write() {
                        fw.parent_kit = Some(kw.clone());
                    }
                }
                for f in &folder_refs {
                    if let Ok(mut fw) = f.write() {
                        fw.parent_kit = Some(kw.clone());
                    }
                }
                k.types = type_refs;
                k.designs = design_refs;
                k.files = file_refs;
                k.folders = folder_refs;
            }
            event_wire::wire_graph_bus(&kit);
            kit
        }

