            let f = Arc::new(RwLock::new(FileStore::from_full_dto(dto)));
            {
                let kw = Arc::downgrade(kit);
                f.write().map_err(|_| SetError::LockPoisoned("file".into()))?.parent_kit = Some(kw);
            }
            g.files.push(f);
            g.invalidate_hash();
            g.invalidate_validation();
