        mod connection {
            use crate::events::KitEvent;

            #[test]
            fn connection_set_gap_triggers_flatten_and_validation() {
                let (kit, _, dg, _, _, cg) = super::common::kit_with_connection();
                let mut rx = kit.read().unwrap().subscribe();
                let c = {
                    let kr = kit.read().unwrap();
                    let d = kr.design(dg.as_str()).unwrap();
                    let dr = d.read().unwrap();
                    dr.connection(cg.as_str()).unwrap().clone()
                };
                c.write().unwrap().set_gap(Some(1.0));
                let evs = super::common::drain(&mut rx);
                assert!(matches!(&evs[0], KitEvent::Changed), "ev0 {:?}", evs.get(0));
                assert!(
                    matches!(
                        &evs[1],
                        KitEvent::Design {
                            design_id,
                            event: crate::events::DesignEvent::Changed,
                        } if *design_id == dg
                    ),
                    "ev1 {:?}",
                    evs.get(1)
                );
                assert!(
                    matches!(
                        &evs[2],
                        KitEvent::Design {
                            design_id,
                            event: crate::events::DesignEvent::Connection {
                                connection_id,
                                event: crate::events::ConnectionEvent::Changed,
                            },
                        } if *design_id == dg && *connection_id == cg
                    ),
                    "ev2 {:?}",
                    evs.get(2)
                );
                assert!(
                    matches!(
                        &evs[3],
                        KitEvent::Design {
                            design_id,
                            event: crate::events::DesignEvent::Connection {
                                connection_id,
                                event: crate::events::ConnectionEvent::FieldChanged(crate::events::ConnectionField::Gap),
                            },
                        } if *design_id == dg && *connection_id == cg
                    ),
                    "ev3 {:?}",
                    evs.get(3)
                );
                assert!(evs.iter().any(|e| matches!(e, KitEvent::FlattenInvalidated { .. })));
                assert!(evs.iter().any(|e| matches!(e, KitEvent::ValidationInvalidated)));
            }
        }

        mod diff_apply {
            use crate::diff::DesignDiff;
            use crate::events::{EntityKind, EntityRef, KitEvent};
            use crate::id::Id;
            use crate::piece::PieceFullDto;
            use crate::typ::TypeIdDto;

            #[test]
            fn apply_design_diff_add_piece_emits_child_added_and_hashes() {
                let (kit, tg, dg, _) = super::common::kit_with_piece();
                let new_piece = Id::new_v7();
                let diff = DesignDiff {
                    pieces: Some(crate::diff::PiecesDiff {
                        added: vec![PieceFullDto { id: new_piece.clone(), r#type: Some(TypeIdDto { id: tg.clone() }), ..Default::default() }],
                        ..Default::default()
                    }),
                    ..Default::default()
                };
                let mut rx = kit.read().unwrap().subscribe();
                kit.write().unwrap().apply_design_diff(dg.as_str(), &diff).unwrap();
                let evs = super::common::drain(&mut rx);
                let child = EntityRef::new(EntityKind::Piece, new_piece);
                assert!(evs.iter().any(|e| matches!(
                    e,
                    KitEvent::ChildAdded { child: c, .. } if *c == child
                )));
                assert!(evs.iter().filter(|e| matches!(e, KitEvent::HashInvalidated { .. })).count() >= 1);
            }
        }

